import {normalizeGames} from './coloring.js';
import {roomArtwork,hydrateFramedArt} from './art-wall-art.js';
import {companionBehavior,PERSONALITIES} from './companion-personality.js';
import {SKINS,PETS,LEVELS,growthFromHistory} from './companions.js';
import {ROOMS,CATEGORIES,SHOP_TIERS,ITEMS,ITEM_BY_ID,SLOTS,WEAR_SLOTS,normalizeHabitat,ownedItems,wallet,coinRewards,buyItem,decorateRoom,equipItem,movePet,toggleWish,homeMilestones,positionPet,resetPositions,clampPosition,removeRoomItem,clearRoom,moveRoomItem,canPlaceInRoom,isMovable,placementBounds,canPlaceAt,clampItemPosition,defaultPlacement,ZONE_NAMES} from './habitat.js';
import {objectArt,itemArt,itemRatio} from './habitat-art.js';
import {companionArt} from './companion-art.js';

export function createHabitatUI({app,modal,storage,history,getOutfit,setOutfit,practice,openArtWall,onRouteChange=()=>{},toast,chime}){
 let section='home',room='lounge',category='all',slot='furniture',wearSlot='head',previewLevel=null,wishesOnly=false,shopTier='all',shopRoom='all',selectedItem=null,arranging=false,moodTimer;
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const read=()=>normalizeHabitat(storage.read('habitat',{}),history());
 const save=state=>storage.write('habitat',state);
 const money=n=>`<span class="leaf-coin" aria-hidden="true">❧</span> ${n}`;
 const badge=(name,active,attr)=>`<button class="habitat-tab ${active?'active':''}" ${attr} aria-pressed="${active}">${name}</button>`;
 function finishPlacement(){selectedItem=null;arranging=false;render();}
 // One listener for the UI lifetime; ignore controls and captured furniture-drag clicks.
 app.ownerDocument.addEventListener('click',e=>{
  if((!arranging&&!selectedItem)||section!=='home'||!app.querySelector('.house-panel')||modal.open)return;
  if(!(e.target instanceof Element)||e.target.closest('button,a,input,select,textarea,label,summary,dialog,[role="button"],[contenteditable="true"]'))return;
  finishPlacement();
 },true);
 function render(){
  clearTimeout(moodTimer);const state=read(),coins=wallet(state,history()),outfit=getOutfit();
  app.innerHTML=`<section class="page-intro habitat-intro"><div><div class="eyebrow"><span></span> A LITTLE HOME, A LOT OF LOVE</div><h1>把小小的努力，住成一个家。</h1><p>陪伙伴长大，也把喜欢的生活慢慢收集起来。</p></div><button class="wallet-button" id="open-wallet" aria-label="查看叶子币收支，余额 ${coins.balance}">${money(coins.balance)}<small>我的叶子币 ↗</small></button></section><nav class="habitat-nav" aria-label="伙伴小屋功能">${[['home','我们的小屋'],['growth','伙伴成长'],['wardrobe','装扮衣橱'],['shop','叶子商店'],['collection','收集手帐']].map(([key,name])=>badge(name,section===key,`data-habitat-section="${key}"`)).join('')}</nav><div id="habitat-content">${section==='home'?home(state):section==='growth'?growth(state):section==='wardrobe'?wardrobe(state):section==='shop'?shop(state):collection(state)}</div><details class="habitat-theme"><summary>小岛主题色 <span>${SKINS[outfit.skin].name}</span></summary><div class="skin-grid">${Object.entries(SKINS).map(([id,s])=>`<button class="skin-choice ${outfit.skin===id?'active':''}" data-skin="${id}" style="--swatch:${s.main};--swatch-bg:${s.tint}" aria-pressed="${outfit.skin===id}"><span>${outfit.skin===id?'✓':''}</span>${s.name}</button>`).join('')}</div></details><p class="local-note">成长积分让伙伴升级 · 叶子币购买好物 · 小屋和收藏自动保存在当前浏览器</p>`;
  bind(state);hydrateFramedArt(app,normalizeGames(storage.read('games',{}),history()).works);
  onRouteChange(routeParams());
 }
 function scene(state,id,mini=false){
  const settings=state.rooms[id],pets=Object.keys(PETS).filter(p=>state.residents[p]===id),all=growthFromHistory(history());
  const wall=ITEM_BY_ID[settings.wall]?.color||(id==='garden'?'#c3e3e5':id==='bedroom'?'#727c9b':'#eee9df'),floor=ITEM_BY_ID[settings.floor]?.color||(id==='garden'?'#96bb7e':'#d6c8b7');
  return `<div class="room-scene room-${id} ${mini?'mini-scene':arranging?'arranging':''} ${settings.floor==='ground-stone'?'stone-path':''}" style="--wall:${wall};--floor:${floor}" aria-label="${ROOMS[id].name}，入住 ${pets.length} 位伙伴"><div class="room-backdrop"></div>${settings.wall&&!['wall-cream'].includes(settings.wall)?'<div class="room-wall-tint"></div>':''}${settings.floor&&!['floor-oak'].includes(settings.floor)?'<div class="room-floor-tint '+(settings.floor==='floor-cloud'?'pale-floor':'')+'"></div>':''}${settings.floor==='ground-stone'?'<div class="garden-path stone-trail"></div>':''}${roomArtwork(normalizeGames(storage.read('games',{}),history()),id,mini)}${settings.objects.map(o=>{const i=ITEM_BY_ID[o.itemId];return `<${mini?'span':'button'} class="placed-object zone-${i.zone} ${!mini&&selectedItem===i.id?'selected':''}" ${mini?'':`data-room-object="${i.id}" aria-label="移动或撤下${i.name}" aria-pressed="${selectedItem===i.id}"`} style="left:${o.x}%;top:${o.y}%;width:${i.size}%;aspect-ratio:${itemRatio(i)};--object-z:${i.zone==='wall'?10:i.zone==='rug'?15:Math.round(o.y)}">${itemArt(i).replace('<svg ',i.zone==='rug'?'<svg preserveAspectRatio="none" ':'<svg ')}</${mini?'span':'button'}>`;}).join('')}<div class="room-residents">${pets.map((pet,i)=>`<${mini?'span':'button'} class="resident" ${mini?'':`data-resident="${pet}" aria-label="移动${PETS[pet].name}，点击打招呼" aria-describedby="room-move-help"`} style="--resident-x:${state.positions[id][pet].x}%;--resident-y:${state.positions[id][pet].y}%;--resident-z:${Math.round(100-state.positions[id][pet].y)};--resident-delay:${i*-.9}s">${companionArt(pet,all[pet].level,state.outfits[pet])}${mini?'':`<span class="resident-name">${PETS[pet].name}</span>`}</${mini?'span':'button'}>`).join('')}</div>${mini?'':'<div class="placement-zone" hidden><span></span></div><div class="room-speech" id="room-speech" role="status"></div>'}</div>`;
 }
 function selectionTools(){const i=ITEM_BY_ID[selectedItem];return i?`<strong>${i.name}</strong><span>${ZONE_NAMES[i.zone]} · 拖动或用方向键移动，点击空白完成</span><button class="secondary" id="remove-selected">撤下物品</button><button class="text-btn" id="finish-placement">完成摆放</button>`:'<span>点击物品可拖动、撤下；绿色框显示物品落点的可放范围。</span>';}
 function roomNav(state){return `<div class="room-tabs" aria-label="选择房间">${Object.entries(ROOMS).map(([id,r])=>`<button data-room="${id}" class="room-tab ${room===id?'active':''}" aria-pressed="${room===id}"><span>${objectArt(r.icon)}</span><strong>${r.short}</strong><small>${Object.values(state.residents).filter(x=>x===id).length} 位伙伴</small></button>`).join('')}</div>`;}
 function home(state){const owned=ownedItems(state),settings=state.rooms[room],finish=['wall','floor'].includes(slot),used=id=>finish?settings[slot]===id:settings.objects.some(o=>o.itemId===id);return `<section class="house-panel panel"><div class="panel-heading"><div><div class="eyebrow">OUR COZY CORNER</div><h2>${ROOMS[room].name}</h2><p>${ROOMS[room].tag}</p></div><button class="secondary" id="toggle-arranging" aria-pressed="${arranging}">${arranging?'完成布置':'布置小屋'}</button></div>${roomNav(state)}${scene(state,room)}<div class="placement-toolbar" id="placement-toolbar" aria-live="polite">${selectionTools()}</div><div class="scene-caption"><span><span id="room-move-help">${arranging?'布置中，伙伴会乖乖让开 · 同类家具可以摆多件':'拖动伙伴调整位置 · 点击打招呼 · 方向键也能移动'}</span><button class="text-btn" id="reset-room-positions">恢复站位</button></span>${room!=='garden'?'<button class="text-btn" id="house-art-wall">布置作品墙 →</button>':''}<button class="text-btn" data-section-link="wardrobe">给伙伴换装 →</button></div></section><div class="house-tools"><section class="panel room-editor"><div class="panel-heading"><h2>给这个房间添点喜欢</h2><button class="text-btn" id="clear-room">清空家具布置</button></div><p class="help-copy">撤下的物品会留在收藏里，随时可以摆回来。这里只展示适合${ROOMS[room].short}的好物。</p><div class="compact-tabs">${Object.entries(SLOTS).map(([key,name])=>badge(name,key===slot,`data-room-slot="${key}"`)).join('')}</div><div class="decoration-shelf">${finish?`<button class="decoration-choice ${settings[slot]===null?'active':''}" id="remove-finish" aria-pressed="${settings[slot]===null}"><span class="empty-hanger">○</span><strong>不使用${SLOTS[slot]}</strong><small>恢复场景底色</small></button>`:''}${ITEMS.filter(i=>i.category===slot&&owned.has(i.id)&&canPlaceInRoom(i.id,room)).map(i=>`<button class="decoration-choice ${used(i.id)?'active':''}" data-decorate="${i.id}" aria-label="在${ROOMS[room].short}摆放${i.name}" aria-pressed="${used(i.id)}">${itemArt(i)}<strong>${i.name}</strong><small>${used(i.id)?finish?'正在使用':'已摆放 · 点击调整':'点击摆放'}</small></button>`).join('')}<button class="decoration-choice add-choice" data-shop-slot="${slot}" data-for-room="${room}"><span>＋</span><strong>发现新好物</strong><small>买一次，适用房间都能用</small></button></div></section><section class="panel resident-manager"><div class="panel-heading"><h2>大家住在哪里？</h2></div>${Object.entries(PETS).map(([id,p])=>`<label class="resident-setting"><span>${companionArt(id,growthFromHistory(history())[id].level,state.outfits[id])}<strong>${p.name}</strong></span><select data-resident-room="${id}" aria-label="${p.name}入住的房间">${Object.entries(ROOMS).map(([key,r])=>`<option value="${key}" ${state.residents[id]===key?'selected':''}>${r.short}</option>`).join('')}</select></label>`).join('')}<p class="help-copy">同一个房间可以住多位伙伴。随时搬家，一起热热闹闹。</p></section></div>`;}
 function petChoices(state){const selected=getOutfit().pet,all=growthFromHistory(history());return `<div class="companion-choices">${Object.entries(PETS).map(([id,p])=>`<button data-companion="${id}" class="companion-choice ${id===selected?'active':''}" aria-pressed="${id===selected}">${companionArt(id,all[id].level,state.outfits[id])}<strong>${p.name}</strong><small>Lv.${all[id].level}${id===selected?' · 陪你练习':''}</small></button>`).join('')}</div>`;}
 function growth(state){const id=getOutfit().pet,p=PETS[id],current=growthFromHistory(history())[id],level=previewLevel??current.level;
  return `<section class="panel companion-selector"><div class="panel-heading"><h2>今天，谁陪你出发？</h2><span>各自成长，一起住在小屋</span></div>${petChoices(state)}</section><section class="panel companion-story"><div class="companion-spotlight" id="interactive-companion">${companionArt(id,level,state.outfits[id],'spotlight-art')}<span class="stage-tag">${level>current.level?'未来形象预览':'已解锁形象'} · Lv.${level}</span><div class="companion-speech" id="companion-speech" role="status">${companionBehavior(id,level).speech}</div><div class="pet-interactions"><button data-pet-action="greet">打个招呼</button><button data-pet-action="happy">摸摸头</button><button data-pet-action="celebrate">庆祝一下</button></div></div><div class="companion-story-copy"><div class="eyebrow">GROW TOGETHER</div><h2>${p.stages[level-1]}</h2><p class="stage-description">${companionBehavior(id,level).description}</p><div class="growth-status"><strong>${current.points}</strong> 成长积分 · 当前 Lv.${current.level}</div><div class="growth-track" role="progressbar" aria-label="伙伴升级进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(current.percent)}"><span style="width:${current.percent}%"></span></div><p class="growth-next">${current.next===null?'已成为守护者，继续收藏一起努力的时光。':`再答对 ${current.remaining} 题，迎接下一次蜕变。`}</p><button class="primary" id="habitat-practice">和${p.name}一起练习</button><p class="help-copy">答对 1 题获得 1 成长积分。成长积分会一直保留，叶子币可以用来装扮小屋。</p></div></section><section class="panel evolution-panel"><div class="panel-heading"><h2>四段旅程，四种模样</h2><span>点击预览每个阶段</span></div><div class="evolution-gallery" aria-label="四阶段成长形象">${LEVELS.map((threshold,i)=>`<button data-evolution="${i+1}" class="evolution-card ${level===i+1?'active':''}" aria-pressed="${level===i+1}"><span class="evolution-number">0${i+1}</span>${companionArt(id,i+1,{},'evolution-art')}<strong>${p.stages[i]}</strong><span>${['幼崽','伙伴','探险家','守护者'][i]} · ${companionBehavior(id,i+1).label}</span><small>${current.level>=i+1?'✓ 已解锁':threshold+' 成长积分'}</small></button>`).join('')}</div></section>`;
 }
 function wardrobe(state){const id=getOutfit().pet,owned=ownedItems(state),equipped=state.outfits[id];return `<section class="panel companion-selector"><div class="panel-heading"><h2>为谁挑一件新装扮？</h2><span>每位伙伴都有自己的搭配</span></div>${petChoices(state)}</section><div class="wardrobe-layout"><section class="panel dressing-mirror"><div class="eyebrow">TODAY'S LITTLE LOOK</div><h2>${PETS[id].name}的今日穿搭</h2><div class="mirror-stage">${companionArt(id,growthFromHistory(history())[id].level,equipped,'dressing-art')}</div><div class="wear-summary">${Object.entries(WEAR_SLOTS).map(([s,label])=>`<span>${label}<strong>${equipped[s]?ITEM_BY_ID[equipped[s]].name:'还没有佩戴'}</strong></span>`).join('')}</div></section><section class="panel wardrobe-inventory"><div class="panel-heading"><h2>我的配饰盒</h2><button class="text-btn" data-shop-slot="accessory">买点新配饰 ↗</button></div><div class="compact-tabs">${Object.entries(WEAR_SLOTS).map(([key,label])=>badge(label,key===wearSlot,`data-wear-slot="${key}"`)).join('')}</div><div class="wardrobe-grid"><button class="decoration-choice ${!equipped[wearSlot]?'active':''}" data-equip="" aria-pressed="${!equipped[wearSlot]}"><span class="empty-hanger">⌁</span><strong>暂不佩戴</strong></button>${ITEMS.filter(i=>i.category==='accessory'&&i.slot===wearSlot&&owned.has(i.id)).map(i=>`<button class="decoration-choice ${equipped[wearSlot]===i.id?'active':''}" data-equip="${i.id}" aria-label="给${PETS[id].name}佩戴${i.name}" aria-pressed="${equipped[wearSlot]===i.id}">${itemArt(i)}<strong>${i.name}</strong><small>${equipped[wearSlot]===i.id?'已佩戴':'点击试戴'}</small></button>`).join('')}</div><p class="help-copy">头饰、围巾和胸章可以自由组合。配饰买一次，四位伙伴都可以佩戴。</p></section></div>`;}
 function shop(state){const owned=ownedItems(state),balance=wallet(state,history()).balance,shown=ITEMS.filter(i=>i.price>0&&(shopRoom==='all'||canPlaceInRoom(i.id,shopRoom))&&(shopTier==='all'||i.tier===shopTier)&&(category==='all'||i.category===category)&&(!wishesOnly||state.wishlist.includes(i.id))).sort((a,b)=>Number(owned.has(a.id))-Number(owned.has(b.id))||a.price-b.price);return `<section class="shop-welcome"><div><div class="eyebrow">THE LEAF & LITTLE THINGS</div><h2>叶子商店</h2><p>一盏灯、一顶帽子，让努力变成喜欢的样子。</p></div><div class="shop-illustration">${itemArt(ITEM_BY_ID['plant-bloom'])}${itemArt(ITEM_BY_ID['head-beret'])}${itemArt(ITEM_BY_ID['lamp-moon'])}</div></section><div class="shop-room-filter" aria-label="按房间挑选">${badge('所有房间',shopRoom==='all','data-shop-room="all"')}${Object.entries(ROOMS).map(([id,r])=>badge(r.short,shopRoom===id,`data-shop-room="${id}"`)).join('')}</div><div class="shop-tiers" aria-label="好物价格档次">${badge('全部档次',shopTier==='all','data-shop-tier="all"')}${Object.entries(SHOP_TIERS).map(([key,tier])=>badge(`${tier.name}<small>${tier.range} 叶子币</small>`,shopTier===key,`data-shop-tier="${key}"`)).join('')}</div><div class="shop-toolbar"><div class="compact-tabs">${Object.entries(CATEGORIES).map(([key,label])=>badge(label,key===category,`data-shop-category="${key}"`)).join('')}</div><button class="text-btn wishlist-toggle" id="wishlist-filter" aria-pressed="${wishesOnly}">${wishesOnly?'显示全部':'♡ 心愿清单'} ${state.wishlist.length?`(${state.wishlist.length})`:''}</button></div><div class="shop-grid">${shown.map(i=>`<article class="shop-item tier-${i.tier}"><button class="shop-art-button" data-item-preview="${i.id}" aria-label="预览${i.name}" style="--item-tint:${i.color}22">${itemArt(i)}</button>${owned.has(i.id)?'<span class="owned-ribbon">已收藏</span>':`<button class="wish-heart ${state.wishlist.includes(i.id)?'wished':''}" data-wish="${i.id}" aria-label="${state.wishlist.includes(i.id)?'移出':'加入'}心愿清单：${i.name}" aria-pressed="${state.wishlist.includes(i.id)}">${state.wishlist.includes(i.id)?'♥':'♡'}</button>`}<div class="shop-item-copy"><span class="shop-tier-tag">${SHOP_TIERS[i.tier].name}</span><small>${CATEGORIES[i.category]}${i.category==='accessory'?' · '+WEAR_SLOTS[i.slot]:''}</small><span class="item-room-tag">${i.category==='accessory'?'四位伙伴通用':i.rooms.length===1?ROOMS[i.rooms[0]].short+'专属':i.rooms.map(r=>ROOMS[r].short).join(' · ')}</span><h3>${i.name}</h3><p>${i.description}</p><div class="shop-item-bottom"><strong>${money(i.price)}</strong><button class="${owned.has(i.id)?'text-btn':'secondary'}" ${owned.has(i.id)?`data-use-item="${i.id}"`:`data-item-preview="${i.id}"`}>${owned.has(i.id)?'去使用':'看看好物'}</button></div></div></article>`).join('')}</div>${shown.length?'':'<div class="empty-state"><h2>这个分类还没有好物</h2><p>试试其他档次或分类，也可以关闭心愿清单筛选。</p></div>'}<div class="shop-earn-strip"><span>${money(balance)} <strong>每一份认真，都能攒下喜欢</strong><small>每填答 1 题 +1 叶子币 · 每轮填满 20 题额外 +10 · 每日首轮再 +10</small></span><button class="primary" id="shop-practice">去赚叶子币</button></div>`;}
 function collection(state){const owned=ownedItems(state),stamps=homeMilestones(state);return `<section class="panel collection-book"><div class="panel-heading"><div><div class="eyebrow">OUR LITTLE MEMORY BOOK</div><h2>小屋收集手帐</h2></div><span class="collection-count">${owned.size}<small> / ${ITEMS.length} 件好物</small></span></div><div class="memory-stamps">${stamps.map(s=>`<div class="memory-stamp ${s.done?'earned':''}"><span>${s.done?'✦':'◇'}</span><strong>${s.name}</strong><small>${s.description}</small><em>${s.done?'已点亮':'等你点亮'}</em></div>`).join('')}</div></section><section class="panel"><div class="panel-heading"><h2>收藏的小小美好</h2><button class="text-btn" data-section-link="shop">继续逛商店 →</button></div><div class="collection-inventory">${ITEMS.filter(i=>owned.has(i.id)).map(i=>`<button class="collection-object" data-use-item="${i.id}">${itemArt(i)}<strong>${i.name}</strong><small>${i.price?'已收藏':'入住礼物'}</small></button>`).join('')}</div></section><section class="panel house-postcards"><div class="panel-heading"><h2>我们的四个小天地</h2><span>点一张明信片，回房间看看</span></div><div class="postcard-grid">${Object.entries(ROOMS).map(([id,r])=>`<button class="room-postcard" data-postcard="${id}">${scene(state,id,true)}<strong>${r.name}</strong></button>`).join('')}</div></section>`;}
 function modalContent(html){modal.classList.add('habitat-modal');document.querySelector('#modal-content').innerHTML=html;modal.showModal();modal.addEventListener('close',()=>modal.classList.remove('habitat-modal'),{once:true});}
 function showItem(id){const item=ITEM_BY_ID[id],state=read(),coins=wallet(state,history()),owned=ownedItems(state).has(id),pet=getOutfit().pet,accessory=item.category==='accessory';
  const preview=accessory?companionArt(pet,growthFromHistory(history())[pet].level,{...state.outfits[pet],[item.slot]:id},'shop-pet-preview'):itemArt(item);
  modalContent(`<div class="item-preview-stage" style="--item-tint:${item.color}33">${preview}</div><div class="item-preview-copy"><div class="eyebrow">${accessory?'试戴效果 · '+PETS[pet].name:item.rooms.map(r=>ROOMS[r].short).join(' / ')+(item.rooms.length===1?'专属':'适用')}</div><h2>${item.name}</h2><p>${item.description}</p><strong class="item-price">${money(item.price)}</strong><small>当前余额 ${coins.balance} 叶子币 · 买一次，永久收藏</small>${accessory?'':`<div class="room-preview-control"><label>房间试摆 <select id="preview-room" aria-label="选择试摆房间">${item.rooms.map(r=>`<option value="${r}" ${r===room?'selected':''}>${ROOMS[r].short}</option>`).join('')}</select></label><small>预览不会改变你的小屋</small></div><div id="item-room-preview"></div>`}<div class="dialog-actions"><button class="secondary" id="close-shop-preview">再逛逛</button><button class="primary" id="purchase-item" ${!owned&&coins.balance<item.price?'disabled':''}>${owned?'去使用':coins.balance<item.price?`还差 ${item.price-coins.balance} 叶子币`:'购买并收藏'}</button></div></div>`);
  if(!accessory){const selector=document.querySelector('#preview-room'),paint=()=>{const r=selector.value,preview=structuredClone(state);preview.residents={};preview.rooms[r]={...preview.rooms[r],objects:[]};if(isMovable(id))preview.rooms[r].objects=[{itemId:id,...defaultPlacement(id,r)}];else preview.rooms[r][item.category]=id;document.querySelector('#item-room-preview').innerHTML=scene(preview,r,true);hydrateFramedArt(modal,normalizeGames(storage.read('games',{}),history()).works);};selector.onchange=paint;paint();}
  document.querySelector('#close-shop-preview').onclick=()=>modal.close();document.querySelector('#purchase-item').onclick=()=>{if(owned){modal.close();useItem(id);return;}try{if(save(buyItem(storage.read('habitat',{}),history(),id))){modal.close();render();chime(true);toast(`已收藏「${item.name}」${accessory?'，去衣橱给伙伴戴上吧！':'，去小屋摆放吧！'}`);}}catch(e){toast(e.message);modal.close();render();}};
 }
 function showWallet(){const state=read(),w=wallet(state,history()),rewards=coinRewards(history()).filter(r=>r.total).reverse().slice(0,5);
  modalContent(`<div class="wallet-details"><div class="eyebrow">LITTLE EFFORT, LITTLE TREASURES</div><h2>我的叶子币</h2><strong class="wallet-total">${money(w.balance)}</strong><div class="wallet-numbers"><span>累计获得 <b>${w.earned}</b></span><span>装扮花费 <b>${w.spent}</b></span></div><p>每填答 1 题获得 1 币。每轮填满 20 题额外获得 10 币，每日第一轮再加 10 币。答题速度不影响奖励。</p><div class="wallet-ledger"><h3>最近的收获</h3>${rewards.map(r=>`<div><span>${new Date(r.date).toLocaleDateString('zh-CN')} · 练习 ${r.base} 题<small>填答 +${r.base}${r.completion?' · 完成奖励 +10':''}${r.daily?' · 今日首轮 +10':''}</small></span><strong>+${r.total}</strong></div>`).join('')}<div><span>欢迎入住小屋<small>每位探险家的第一份礼物</small></span><strong>+80</strong></div><h3>最近的收藏</h3>${state.purchases.slice(-5).reverse().map(p=>`<div><span>${ITEM_BY_ID[p.itemId].name}</span><strong>−${p.paid}</strong></div>`).join('')||'<p>还没有花费，去发现第一件心头好吧。</p>'}</div><button class="primary" id="close-wallet">收好我的叶子币</button></div>`);
  document.querySelector('#close-wallet').onclick=()=>modal.close();
 }
 function useItem(id){const item=ITEM_BY_ID[id];if(item.category==='accessory'){section='wardrobe';wearSlot=item.slot;}else{section='home';slot=item.category;if(!canPlaceInRoom(id,room))room=item.rooms[0];selectedItem=null;arranging=true;}render();}
 function mutate(action,message){try{if(save(action())){render();if(message)toast(message);}}catch(e){toast(e.message);}}
 function react(pet,action='greet',resident=false){clearTimeout(moodTimer);const target=resident?app.querySelector(`[data-resident="${pet}"]`):app.querySelector('#interactive-companion'),speech=app.querySelector(resident?'#room-speech':'#companion-speech');if(!target||!speech)return;target.dataset.mood=action;const texts=PERSONALITIES[pet].replies;speech.textContent=texts[action];speech.classList.add('visible');chime(action==='celebrate');moodTimer=setTimeout(()=>{delete target.dataset.mood;speech.classList.remove('visible');},3000);}
 function bindDragging(state){
  app.querySelectorAll('[data-resident]').forEach(b=>{
   const pet=b.dataset.resident,scene=b.closest('.room-scene');let drag=null,moved=false;
   const paint=p=>{b.style.setProperty('--resident-x',p.x+'%');b.style.setProperty('--resident-y',p.y+'%');b.style.setProperty('--resident-z',Math.round(100-p.y));};
   b.onclick=()=>{if(moved){moved=false;return;}react(pet,'greet',true);};
   b.onpointerdown=e=>{if(e.button!==0)return;moved=false;const rect=scene.getBoundingClientRect();drag={pointer:e.pointerId,x:e.clientX,y:e.clientY,origin:state.positions[room][pet],rect,current:state.positions[room][pet]};b.setPointerCapture(e.pointerId);};
   b.onpointermove=e=>{if(!drag||drag.pointer!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!moved&&Math.hypot(dx,dy)<6)return;moved=true;b.classList.add('dragging');drag.current=clampPosition({x:drag.origin.x+dx/drag.rect.width*100,y:drag.origin.y-dy/drag.rect.height*100});paint(drag.current);};
   b.onpointerup=e=>{if(!drag||drag.pointer!==e.pointerId)return;const point=drag.current;drag=null;b.classList.remove('dragging');if(b.hasPointerCapture(e.pointerId))b.releasePointerCapture(e.pointerId);if(moved){const next=positionPet(storage.read('habitat',{}),history(),room,pet,point);if(save(next)){state.positions[room][pet]=point;toast(PETS[pet].name+'的新位置已保存');}else paint(state.positions[room][pet]);}};
   b.onpointercancel=()=>{drag=null;moved=false;b.classList.remove('dragging');paint(state.positions[room][pet]);};
   b.onkeydown=e=>{const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,1],ArrowDown:[0,-1]}[e.key];if(!delta)return;e.preventDefault();const step=e.shiftKey?5:2,old=state.positions[room][pet],point=clampPosition({x:old.x+delta[0]*step,y:old.y+delta[1]*step});if(save(positionPet(storage.read('habitat',{}),history(),room,pet,point))){state.positions[room][pet]=point;paint(point);}};
  });
 }
 function updateSelection(){
  const scene=app.querySelector('.house-panel .room-scene'),zone=scene?.querySelector('.placement-zone'),toolbar=app.querySelector('#placement-toolbar');if(!zone||!toolbar)return;
  const bounds=placementBounds(room,selectedItem);zone.hidden=!bounds;
  if(bounds){zone.style.cssText=`left:${bounds.left}%;top:${bounds.top}%;width:${bounds.right-bounds.left}%;height:${bounds.bottom-bounds.top}%`;zone.querySelector('span').textContent=ZONE_NAMES[ITEM_BY_ID[selectedItem].zone]+' · 把底部圆点放在框内';}
  scene.querySelectorAll('[data-room-object]').forEach(b=>{const chosen=b.dataset.roomObject===selectedItem;b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',chosen);});
  toolbar.innerHTML=selectionTools();
  toolbar.querySelector('#remove-selected')?.addEventListener('click',()=>{const id=selectedItem;selectedItem=null;mutate(()=>removeRoomItem(storage.read('habitat',{}),history(),room,id),'物品已收回收藏');});
  toolbar.querySelector('#finish-placement')?.addEventListener('click',finishPlacement);
 }
 function bindObjects(state){
  app.querySelectorAll('[data-room-object]').forEach(b=>{
   const id=b.dataset.roomObject,scene=b.closest('.room-scene'),zone=scene.querySelector('.placement-zone');let drag=null,moved=false;
   const object=()=>state.rooms[room].objects.find(o=>o.itemId===id),paint=p=>{b.style.left=p.x+'%';b.style.top=p.y+'%';if(ITEM_BY_ID[id].zone==='ground')b.style.setProperty('--object-z',Math.round(p.y));};
   const choose=()=>{selectedItem=id;updateSelection();};
   b.onclick=()=>{if(moved){moved=false;return;}choose();};
   b.onpointerdown=e=>{if(e.button!==0)return;choose();moved=false;drag={pointer:e.pointerId,x:e.clientX,y:e.clientY,origin:{...object()},current:{...object()},rect:scene.getBoundingClientRect()};b.setPointerCapture(e.pointerId);};
   b.onpointermove=e=>{if(!drag||drag.pointer!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!moved&&Math.hypot(dx,dy)<5)return;moved=true;drag.current={x:drag.origin.x+dx/drag.rect.width*100,y:drag.origin.y+dy/drag.rect.height*100};paint(drag.current);b.classList.add('dragging');const valid=canPlaceAt(room,id,drag.current);zone.classList.toggle('invalid',!valid);b.classList.toggle('invalid',!valid);};
   const end=cancel=>{if(!drag)return;const old=drag.origin,point=drag.current,pointer=drag.pointer;drag=null;b.classList.remove('dragging','invalid');zone.classList.remove('invalid');if(b.hasPointerCapture(pointer))b.releasePointerCapture(pointer);if(cancel||!moved){paint(old);return;}if(!canPlaceAt(room,id,point)){paint(old);toast('放在绿色框内哦，物品已回到原位');return;}if(save(moveRoomItem(storage.read('habitat',{}),history(),room,id,point))){Object.assign(object(),point);toast('新位置已保存');}else paint(old);};
   b.onpointerup=()=>end(false);b.onpointercancel=()=>end(true);b.onlostpointercapture=()=>{if(drag)end(true);};
   b.onkeydown=e=>{const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(!delta)return;e.preventDefault();choose();const old=object(),step=e.shiftKey?5:2,point=clampItemPosition(room,id,{x:old.x+delta[0]*step,y:old.y+delta[1]*step});if(save(moveRoomItem(storage.read('habitat',{}),history(),room,id,point))){Object.assign(old,point);paint(point);}};
  });
 }
 function bind(state){
  app.querySelector('#house-art-wall')?.addEventListener('click',()=>openArtWall(room));
  app.querySelectorAll('[data-house-art]').forEach(b=>b.onclick=()=>openArtWall(b.dataset.houseArt));
  app.querySelectorAll('[data-shop-room]').forEach(b=>b.onclick=()=>{shopRoom=b.dataset.shopRoom;render();});
  app.querySelector('#toggle-arranging')?.addEventListener('click',()=>{arranging=!arranging;selectedItem=null;render();});
  app.querySelector('#clear-room')?.addEventListener('click',()=>{selectedItem=null;mutate(()=>clearRoom(storage.read('habitat',{}),history(),room),'已清空布置，物品都收回收藏了');});
  app.querySelector('#remove-finish')?.addEventListener('click',()=>mutate(()=>removeRoomItem(storage.read('habitat',{}),history(),room,state.rooms[room][slot])));
  bindObjects(state);updateSelection();
  app.querySelectorAll('[data-shop-tier]').forEach(b=>b.onclick=()=>{shopTier=b.dataset.shopTier;render();});
  app.querySelectorAll('[data-habitat-section],[data-section-link]').forEach(b=>b.onclick=()=>{section=b.dataset.habitatSection||b.dataset.sectionLink;previewLevel=null;render();});
  app.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{room=b.dataset.room;selectedItem=null;render();});
  app.querySelectorAll('[data-postcard]').forEach(b=>b.onclick=()=>{section='home';room=b.dataset.postcard;selectedItem=null;render();});
  app.querySelectorAll('[data-room-slot]').forEach(b=>b.onclick=()=>{slot=b.dataset.roomSlot;render();});
  app.querySelectorAll('[data-decorate]').forEach(b=>b.onclick=()=>{selectedItem=isMovable(b.dataset.decorate)?b.dataset.decorate:null;arranging=true;mutate(()=>decorateRoom(storage.read('habitat',{}),history(),room,b.dataset.decorate),'已摆放，可以拖动调整位置');app.querySelector('.house-panel .room-scene')?.scrollIntoView({block:'center',behavior:'instant'});if(selectedItem)app.querySelector(`[data-room-object="${selectedItem}"]`)?.focus({preventScroll:true});});
  app.querySelectorAll('[data-resident-room]').forEach(s=>s.onchange=()=>mutate(()=>movePet(storage.read('habitat',{}),history(),s.dataset.residentRoom,s.value)));
  bindDragging(state);app.querySelector('#reset-room-positions')?.addEventListener('click',()=>mutate(()=>resetPositions(storage.read('habitat',{}),history(),room),'已恢复整齐站位'));
  app.querySelectorAll('[data-companion]').forEach(b=>b.onclick=()=>{setOutfit({...getOutfit(),pet:b.dataset.companion});previewLevel=null;render();});
  app.querySelectorAll('[data-evolution]').forEach(b=>b.onclick=()=>{previewLevel=+b.dataset.evolution;render();});
  app.querySelectorAll('[data-pet-action]').forEach(b=>b.onclick=()=>react(getOutfit().pet,b.dataset.petAction));
  app.querySelectorAll('[data-wear-slot]').forEach(b=>b.onclick=()=>{wearSlot=b.dataset.wearSlot;render();});
  app.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>mutate(()=>equipItem(storage.read('habitat',{}),history(),getOutfit().pet,wearSlot,b.dataset.equip||null),'今日穿搭已保存'));
  app.querySelectorAll('[data-shop-slot]').forEach(b=>b.onclick=()=>{section='shop';category=b.dataset.shopSlot;wishesOnly=false;shopRoom=b.dataset.forRoom||'all';render();});
  app.querySelectorAll('[data-shop-category]').forEach(b=>b.onclick=()=>{category=b.dataset.shopCategory;render();});
  app.querySelectorAll('[data-item-preview]').forEach(b=>b.onclick=()=>showItem(b.dataset.itemPreview));
  app.querySelectorAll('[data-use-item]').forEach(b=>b.onclick=()=>useItem(b.dataset.useItem));
  app.querySelectorAll('[data-wish]').forEach(b=>b.onclick=()=>mutate(()=>toggleWish(storage.read('habitat',{}),history(),b.dataset.wish)));
  app.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{setOutfit({...getOutfit(),skin:b.dataset.skin});render();});
  app.querySelector('#wishlist-filter')?.addEventListener('click',()=>{wishesOnly=!wishesOnly;render();});
  app.querySelector('#open-wallet').onclick=showWallet;
  app.querySelector('#habitat-practice')?.addEventListener('click',practice);app.querySelector('#shop-practice')?.addEventListener('click',practice);
 }
 window.addEventListener('storage',e=>{if(['math-island-v1:games','math-island-v1:history'].includes(e.key)&&app.querySelector('#habitat-content')&&!modal.open)render();});
 function routeParams(){return {section,room};}
 function openRoute(params={}){
  section=['home','growth','wardrobe','shop','collection'].includes(params.section)?params.section:'home';
  room=Object.hasOwn(ROOMS,params.room)?params.room:'lounge';
  selectedItem=null;arranging=false;previewLevel=null;render();
 }
 return {render,routeParams,openRoute,showRoom:id=>{if(Object.hasOwn(ROOMS,id))room=id;section='home';selectedItem=null;arranging=false;render();}};
}
